package com.yeyamo_mobile.api.notification_service.application;
import java.time.Instant;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.yeyamo_mobile.api.notification_service.application.port.*;import com.yeyamo_mobile.api.notification_service.domain.*;
@Service public class DeliveryService{private final DeliveryRepositoryPort deliveries;private final NotificationRepositoryPort notifications;private final Map<NotificationChannel,ChannelSender>senders;private final int maxAttempts;private final long baseDelay;public DeliveryService(DeliveryRepositoryPort d,NotificationRepositoryPort n,List<ChannelSender>s,@Value("${notification.delivery.max-attempts:5}")int max,@Value("${notification.delivery.base-delay-seconds:30}")long delay){deliveries=d;notifications=n;senders=new EnumMap<>(NotificationChannel.class);s.forEach(x->senders.put(x.channel(),x));maxAttempts=Math.max(1,max);baseDelay=Math.max(1,delay);}@Transactional public int dispatch(int limit){int count=0;for(Delivery d:deliveries.findDue(Instant.now(),Math.min(100,Math.max(1,limit)))){Notification n=notifications.findById(d.notificationId()).orElse(null);if(n==null)continue;try{ChannelSender sender=senders.get(d.channel());if(sender==null)throw new IllegalStateException("No sender for "+d.channel());sender.send(d,n);deliveries.save(d.sent(Instant.now()));}catch(RuntimeException e){deliveries.save(d.failed(e.getMessage(),Instant.now(),maxAttempts,baseDelay));}count++;}return count;}}
